38: /**
39:  * class MarkdownIt
40:  *
41:  * Main parser/renderer class.
42:  *
43:  * ##### Usage
44:  *
45:  * ```javascript
46:  * // node.js, "classic" way:
47:  * var MarkdownIt = require('markdown-it'),
48:  *     md = new MarkdownIt();
49:  * var result = md.render('# markdown-it rulezz!');
50:  *
51:  * // node.js, the same, but with sugar:
52:  * var md = require('markdown-it')();
53:  * var result = md.render('# markdown-it rulezz!');
54:  *
55:  * // browser without AMD, added to "window" on script load
56:  * // Note, there are no dash.
57:  * var md = window.markdownit();
58:  * var result = md.render('# markdown-it rulezz!');
59:  * ```
60:  *
61:  * Single line rendering, without paragraph wrap:
62:  *
63:  * ```javascript
64:  * var md = require('markdown-it')();
65:  * var result = md.renderInline('__markdown-it__ rulezz!');
66:  * ```
67:  **/
68: 
69: /**
70:  * new MarkdownIt([presetName, options])
71:  * - presetName (String): optional, `commonmark` / `zero`
72:  * - options (Object)
73:  *
74:  * Creates parser instanse with given config. Can be called without `new`.
75:  *
76:  * ##### presetName
77:  *
78:  * MarkdownIt provides named presets as a convenience to quickly
79:  * enable/disable active syntax rules and options for common use cases.
80:  *
81:  * - ["commonmark"](https://github.com/markdown-it/markdown-it/blob/master/lib/presets/commonmark.js) -
82:  *   configures parser to strict [CommonMark](http://commonmark.org/) mode.
83:  * - [default](https://github.com/markdown-it/markdown-it/blob/master/lib/presets/default.js) -
84:  *   similar to GFM, used when no preset name given. Enables all available rules,
85:  *   but still without html, typographer & autolinker.
86:  * - ["zero"](https://github.com/markdown-it/markdown-it/blob/master/lib/presets/zero.js) -
87:  *   all rules disabled. Useful to quickly setup your config via `.enable()`.
88:  *   For example, when you need only `bold` and `italic` markup and nothing else.
89:  *
90:  * ##### options:
91:  *
92:  * - __html__ - `false`. Set `true` to enable HTML tags in source. Be careful!
93:  *   That's not safe! You may need external sanitizer to protect output from XSS.
94:  *   It's better to extend features via plugins, instead of enabling HTML.
95:  * - __xhtmlOut__ - `false`. Set `true` to add '/' when closing single tags
96:  *   (`<br />`). This is needed only for full CommonMark compatibility. In real
97:  *   world you will need HTML output.
98:  * - __breaks__ - `false`. Set `true` to convert `\n` in paragraphs into `<br>`.
99:  * - __langPrefix__ - `language-`. CSS language class prefix for fenced blocks.
100:  *   Can be useful for external highlighters.
101:  * - __linkify__ - `false`. Set `true` to autoconvert URL-like text to links.
102:  * - __typographer__  - `false`. Set `true` to enable [some language-neutral
103:  *   replacement](https://github.com/markdown-it/markdown-it/blob/master/lib/rules_core/replacements.js) +
104:  *   quotes beautification (smartquotes).
105:  * - __quotes__ - `“”‘’`, string. Double + single quotes replacement pairs, when
106:  *   typographer enabled and smartquotes on. Set doubles to '«»' for Russian,
107:  *   '„“' for German.
108:  * - __highlight__ - `null`. Highlighter function for fenced code blocks.
109:  *   Highlighter `function (str, lang)` should return escaped HTML. It can also
110:  *   return empty string if the source was not changed and should be escaped externaly.
111:  *
112:  * ##### Example
113:  *
114:  * ```javascript
115:  * // commonmark mode
116:  * var md = require('markdown-it')('commonmark');
117:  *
118:  * // default mode
119:  * var md = require('markdown-it')();
120:  *
121:  * // enable everything
122:  * var md = require('markdown-it')({
123:  *   html: true,
124:  *   linkify: true,
125:  *   typographer: true
126:  * });
127:  * ```
128:  *
129:  * ##### Syntax highlighting
130:  *
131:  * ```js
132:  * var hljs = require('highlight.js') // https://highlightjs.org/
133:  *
134:  * var md = require('markdown-it')({
135:  *   highlight: function (str, lang) {
136:  *     if (lang && hljs.getLanguage(lang)) {
137:  *       try {
138:  *         return hljs.highlight(lang, str).value;
139:  *       } catch (__) {}
140:  *     }
141:  *
142:  *     try {
143:  *       return hljs.highlightAuto(str).value;
144:  *     } catch (__) {}
145:  *
146:  *     return ''; // use external default escaping
147:  *   }
148:  * });
149:  * ```
150:  **/
151: function MarkdownIt(presetName, options) {
152:   if (!(this instanceof MarkdownIt)) {
153:     return new MarkdownIt(presetName, options);
154:   }
155: 
156:   if (!options) {
157:     if (!utils.isString(presetName)) {
158:       options = presetName || {};
159:       presetName = 'default';
160:     }
161:   }
